mapper.select:
SELECT * FROM (
SELECT u.u_idx AS userIdx, u.u_id AS userId, u.u_name AS userName, u.u_email AS userEmail, u.u_phone AS userPhone, u.u_addr AS userAddr, u.u_created AS userCreated, u.u_active AS userActive, (SELECT COUNT(*) FROM reservation r WHERE r.u_idx = u.u_idx) AS reserveCnt, 'user' AS memberType, '' AS partnerNumber FROM user u
SELECT p.p_idx AS userIdx, p.p_id AS userId, p.p_name AS userName, p.p_email AS userEmail, p.p_phone AS userPhone, p.p_addr AS userAddr, NULL AS userCreated, p.p_active AS userActive, 0 AS reserveCnt, 'partner' AS memberType, p.p_number AS partnerNumber FROM partner p
SELECT u.u_idx AS userIdx, u.u_id AS userId, u.u_name AS userName, u.u_email AS userEmail, u.u_phone AS userPhone, u.u_addr AS userAddr, u.u_created AS userCreated, u.u_active AS userActive, (SELECT COUNT(*) FROM reservation r WHERE r.u_idx = u.u_idx) AS reserveCnt, 'user' AS memberType, '' AS partnerNumber FROM user u
UNION ALL SELECT p.p_idx AS userIdx, p.p_id AS userId, p.p_name AS userName, p.p_email AS userEmail, p.p_phone AS userPhone, p.p_addr AS userAddr, NULL AS userCreated, p.p_active AS userActive, 0 AS reserveCnt, 'partner' AS memberType, p.p_number AS partnerNumber FROM partner p
) AS combined ORDER BY userCreated DESC LIMIT #{numPerPage} OFFSET #{offset}
